import xml.etree.ElementTree as ET

tree = ET.parse('/tmp/hwpx_verify/Contents/section0.xml')
root = tree.getroot()
ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

for p in root.findall('.//hp:p', ns):
    pid = p.get('id')
    texts = []
    for t in p.findall('.//hp:t', ns):
        if t.text:
            texts.append(t.text)
    if texts:
        print(f"  Paragraph {pid}: {' '.join(texts)}")
EOF

